define(["core/ajax","core/notification","core/modal_factory","core/modal_events","core/str"],function(Ajax,Notification,ModalFactory,ModalEvents,Str){var submitForm=function(form){if(!form.querySelector('input[name="finishattempt"]')){var hidden=document.createElement("input");hidden.type="hidden";hidden.name="finishattempt";hidden.value="1";form.appendChild(hidden)}form.submit()};return{init:function(props){if(!document.getElementById("page-mod-quiz-summary"))return;var submitBtn=document.querySelector(".mod_quiz-next-nav")||document.querySelector('button[type="submit"]');if(!submitBtn)return;var form=submitBtn.closest("form");if(!form)return;submitBtn.addEventListener("click",function(e){e.preventDefault();e.stopImmediatePropagation();Str.get_strings([{key:"quizfinish:modal_title",component:"quizaccess_proctoring"},{key:"quizfinish:modal_body",component:"quizaccess_proctoring"},{key:"quizfinish:modal_submit",component:"quizaccess_proctoring"},{key:"quizfinish:modal_processing",component:"quizaccess_proctoring"}]).then(function(strings){return ModalFactory.create({type:ModalFactory.types.SAVE_CANCEL,title:strings[0],body:strings[1]}).then(function(modal){modal.setSaveButtonText(strings[2]);modal.getRoot().on(ModalEvents.save,function(ev){ev.preventDefault();var saveBtn=modal.getRoot().find('[data-action="save"]');saveBtn.prop("disabled",true).text(strings[3]);Ajax.call([{methodname:"quizaccess_proctoring_trigger_analysis",args:{courseid:props.courseid,quizid:props.quizid,attemptid:props.status}}])[0].done(function(){modal.destroy();submitForm(form)}).fail(function(){modal.destroy();submitForm(form)})});modal.show();return modal})}).catch(Notification.exception)},true)}}});